import{_ as a,a as t,c as o,ac as l}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第二册：实践与进步 · Lesson 17 Always young","description":"学习 一般现在时与习惯，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 17 Always young","description":"学习 一般现在时与习惯，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 一般现在时与习惯，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 16 A polite request","link":"/life/english/new-concept/book-2/unit-01/lesson-016"},"next":{"text":"第二册：实践与进步 · Lesson 18 He often does this!","link":"/life/english/new-concept/book-2/unit-01/lesson-018"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 16 A polite request","link":"/life/english/new-concept/book-2/unit-01/lesson-016"},"next":{"text":"第二册：实践与进步 · Lesson 18 He often does this!","link":"/life/english/new-concept/book-2/unit-01/lesson-018"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/lesson-017.md","filePath":"life/english/new-concept/book-2/unit-01/lesson-017.md"}'),n={name:"life/english/new-concept/book-2/unit-01/lesson-017.md"};function s(i,e,r,h,d,c){return t(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="第二册-实践与进步-·-lesson-17-always-young" tabindex="-1">第二册：实践与进步 · Lesson 17 Always young <a class="header-anchor" href="#第二册-实践与进步-·-lesson-17-always-young" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 17 Always young&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>有人始终精神饱满，不能仅凭外表判断年龄；练习频率副词和表语形容词的放置。本课的语言观察是：looks young 中 looks 是系动词，后接形容词 young；always 通常放在 looks 前，若谓语是 is 则通常放在 is 后。完成学习后，请介绍一位有活力的成年人，描述习惯与精神状态，不凭外表推断年龄。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>age</td><td>/eɪdʒ/</td><td>n.</td><td>年龄</td><td>at an early age</td></tr><tr><td>appear</td><td>/əˈpɪə/</td><td>v.</td><td>显得；出现</td><td>appear calm</td></tr><tr><td>stage</td><td>/steɪdʒ/</td><td>n.</td><td>舞台；阶段</td><td>on stage</td></tr><tr><td>adult</td><td>/ˈædʌlt/</td><td>n.</td><td>成年人</td><td>an adult learner</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>look young — 看上去年轻，look 后接形容词</li><li>take part in — 参与活动，in 不可随意省略</li></ul><h2 id="语法讲解-一般现在时与习惯" tabindex="-1">语法讲解：一般现在时与习惯 <a class="header-anchor" href="#语法讲解-一般现在时与习惯" aria-label="Permalink to &quot;语法讲解：一般现在时与习惯&quot;">​</a></h2><p>一般现在时可以描述习惯、规律和当前相对稳定的状态。第三人称单数主语的实义动词通常加 -s；使用 does 或 does not 后，动词回到原形。频率副词常放在实义动词前、be 动词后，但句首句尾也有特定用法。正在发生的临时动作通常另用进行时，不能仅因句中出现 today 就自动选一般现在时或现在进行时。本课应用：looks young 中 looks 是系动词，后接形容词 young；always 通常放在 looks 前，若谓语是 is 则通常放在 is 后。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>My aunt always looks cheerful before a performance.</p></blockquote><p>我姑姑每次演出前看起来总是很愉快。</p><p>My aunt 是主语，looks 是系动词，cheerful 是表语；always 表示频率，不修饰形容词程度。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>looks cheerfully 若没有其他内容不能表达“看起来愉快”；此处用 cheerful。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>比较 looks 的 /s/ 与 practises 的 /ɪz/；读出 before a performance 的词组重音。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>My aunt always looks cheerful before a performance. She practises with a community theatre group. Nobody in the group asks her age.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>介绍一位有活力的成年人，描述习惯与精神状态，不凭外表推断年龄。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：My aunt 是主语，looks 是系动词，cheerful 是表语；always 表示频率，不修饰形容词程度。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：looks cheerfully 若没有其他内容不能表达“看起来愉快”；此处用 cheerful。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选 cheerful/cheerfully：She looks ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> cheerful</p><p><strong>解析：</strong> 系动词 looks 后用形容词作表语。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>姑姑参加什么团体？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> A community theatre group.</p><p><strong>解析：</strong> 示范说明是社区剧团，未给出职业身份。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将 always 放进 She is cheerful。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She is always cheerful.</p><p><strong>解析：</strong> 频率副词通常位于 be 动词之后。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：一般现在时与习惯。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-016">上一课</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-018">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const k=a(n,[["render",s]]);export{p as __pageData,k as default};
